    def seg(self, x, text, speed):
        b = UIButton(x, 8, 38, 32, text, Cyber.mono(Font.BOLD, 14), _j.Fn(lambda : self.screen.set_speed(speed)))
        b.set_flat(True)
        _j_add(self.buttons, b)
